// Thin WebSocket client. The lobby server always lives on port 3000,
// whether the page came from vite dev (5173) or the production server.
const listeners = {};

export const net = {
  id: null,
  ws: null,
  get connected() { return this.ws && this.ws.readyState === WebSocket.OPEN; },

  on(type, fn) { listeners[type] = fn; },

  send(obj) {
    if (this.connected) this.ws.send(JSON.stringify(obj));
  },

  connect() {
    if (this.connected) return Promise.resolve();
    return new Promise((resolve, reject) => {
      const url = `ws://${location.hostname}:3000`;
      const ws = new WebSocket(url);
      const timeout = setTimeout(() => { ws.close(); reject(new Error('timeout')); }, 4000);
      ws.onopen = () => { this.ws = ws; };
      ws.onmessage = (ev) => {
        let msg;
        try { msg = JSON.parse(ev.data); } catch { return; }
        if (msg.t === 'welcome') {
          this.id = msg.id;
          clearTimeout(timeout);
          resolve();
        }
        if (listeners[msg.t]) listeners[msg.t](msg);
      };
      ws.onerror = () => { clearTimeout(timeout); reject(new Error('connect failed')); };
      ws.onclose = () => {
        const wasConnected = this.ws === ws;
        this.ws = null;
        if (wasConnected && listeners.close) listeners.close();
      };
    });
  },
};
